import React, { useState, useEffect } from "react";
import axios from "axios";
import { Link } from "react-router-dom";

const Funds = () => {
  const apiUrl = `http://${window.location.hostname}:3002`;

  const [funds, setFunds] = useState(null);

  useEffect(() => {
    axios.get(`${apiUrl}/api/funds`, {
      withCredentials: true
    })
    .then((res) => {
      setFunds(res.data);
    })
    .catch((err) => {
      console.log("Failed to fetch funds:", err);
    });
  }, []);

  if (!funds) {
    return <p>Loading funds...</p>;
  }

  return (
    <>
      <div className="funds">
        <p>Instant, zero-cost fund transfers with UPI</p>

        <Link className="btn btn-green">Add funds</Link>
        <Link className="btn btn-blue">Withdraw</Link>
      </div>

      <div className="row">
        <div className="col">
          <span><p>Equity</p></span>

          <div className="table">

            <div className="data">
              <p>Available margin</p>
              <p className="imp colored">
                {funds.availableCash.toFixed(2)}
              </p>
            </div>

            <div className="data">
              <p>Used margin</p>
              <p className="imp">
                {funds.usedMargin.toFixed(2)}
              </p>
            </div>

            <div className="data">
              <p>Available cash</p>
              <p className="imp">
                {funds.availableCash.toFixed(2)}
              </p>
            </div>

            <hr />

            <div className="data">
              <p>Opening Balance</p>
              <p>{funds.openingBalance.toFixed(2)}</p>
            </div>

            <div className="data">
              <p>Payin</p>
              <p>0.00</p>
            </div>

            <div className="data">
              <p>SPAN</p>
              <p>0.00</p>
            </div>

            <div className="data">
              <p>Delivery margin</p>
              <p>0.00</p>
            </div>

            <div className="data">
              <p>Exposure</p>
              <p>0.00</p>
            </div>

            <div className="data">
              <p>Options premium</p>
              <p>0.00</p>
            </div>

            <hr />

            <div className="data">
              <p>Collateral (Liquid funds)</p>
              <p>0.00</p>
            </div>

            <div className="data">
              <p>Collateral (Equity)</p>
              <p>0.00</p>
            </div>

            <div className="data">
              <p>Total Collateral</p>
              <p>0.00</p>
            </div>

          </div>
        </div>

        <div className="col">
          <div className="commodity">
            <p>You don't have a commodity account</p>
            <Link className="btn btn-blue">Open Account</Link>
          </div>
        </div>
      </div>
    </>
  );
};

export default Funds;


// ### What became dynamic?

// Previously you had:

// ```text
// Available margin    4,043.10
// Used margin         3,757.30
// Available cash      4,043.10
// Opening Balance     4,043.10
// ```

// Those were just numbers sitting in the JSX.

// Now React does:

// ```text
// GET /api/funds
//        ↓
// MongoDB
//        ↓
// Funds document
//        ↓
// setFunds(res.data)
//        ↓
// UI displays the values
// ```

// So your current screen should show:

// ```text
// Available margin    ₹10,000.00
// Used margin         ₹0.00
// Available cash      ₹10,000.00
// Opening Balance     ₹10,000.00
// ```

// ### ⚠️ One thing we have NOT done yet

// Your **BUY/SELL controller still doesn't modify `FundsModel`**.

// So right now, if you buy ₹2,000 worth of stock:

// ```text
// Holdings  ✅ changes
// Orders    ✅ changes
// Funds     ❌ still says ₹10,000
// ```

// That's the **next important step**.

// We should modify `addNewOrder` so that:

// **BUY ₹2,000**

// ```text
// Available Cash
// ₹10,000 → ₹8,000
// ```

// and:

// **SELL ₹500**

// ```text
// Available Cash
// ₹8,000 → ₹8,500
// ```

// That will make the Funds page actually behave like a trading application rather than just displaying database numbers. 🚀
